def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = np.full((3, 3), bg, dtype=int)
    emit(out, "Allocate a 3x3 canvas: four 2x2 corner blocks will overlap on it.")
    corners = [
        ("top-left", (0, 0), (0, 0)),
        ("top-right", (0, W - 2), (0, 1)),
        ("bottom-left", (H - 2, 0), (1, 0)),
        ("bottom-right", (H - 2, W - 2), (1, 1)),
    ]
    for name, (sy, sx), (dy, dx) in corners:
        block = g[sy:sy + 2, sx:sx + 2]
        for y in range(2):
            for x in range(2):
                if block[y, x] != bg:
                    out[dy + y, dx + x] = block[y, x]
        emit(out, f"Overlay the {name} 2x2 corner block onto the {name} of the 3x3 canvas (coloured cells win).")
    return out
